// Normalizador de Entrada Multimodal — Sandbox Movilnet (:8025)
// Gobernanza: Invariante Zero-PII y Aislamiento Hermético de Producción

const items = $input.all();
const output = [];

for (const item of items) {
  const json = item.json || {};
  const binary = item.binary || {};

  // Detección de teléfono de origen
  let phone = json.phone_number || json.from || json.sender || (json.entry?.[0]?.changes?.[0]?.value?.messages?.[0]?.from) || "+584166251587";
  if (typeof phone === 'string' && !phone.startsWith('+') && phone.length === 11) {
    phone = '+58' + phone.substring(1);
  }

  // Detección de archivo y payload
  let filename = json.filename || "inbound_asset.bin";
  let fileBase64 = "";
  let mediaType = "DOCUMENT";

  // Si n8n recibió datos binarios directos en la petición multipart/form-data
  const firstBinaryKey = Object.keys(binary)[0];
  if (firstBinaryKey && binary[firstBinaryKey]) {
    const binObj = binary[firstBinaryKey];
    filename = binObj.fileName || filename;
    fileBase64 = binObj.data || "";
    const mime = (binObj.mimeType || "").toLowerCase();
    if (mime.includes("audio") || mime.includes("ogg")) mediaType = "AUDIO";
    else if (mime.includes("image")) mediaType = "IMAGE";
    else if (mime.includes("video")) mediaType = "VIDEO";
    else mediaType = "DOCUMENT";
  } else if (json.file_base64) {
    fileBase64 = json.file_base64;
    filename = json.filename || "archivo.bin";
  } else if (json.text_simulation) {
    filename = "nota_voz.ogg";
  }

  output.push({
    json: {
      phone_number: phone,
      filename: filename,
      file_base64: fileBase64,
      text_simulation: json.text_simulation || "",
      channel: "WHATSAPP_SANDBOX_STAGE",
      timestamp_iso: new Date().toISOString()
    }
  });
}

return output;
